def fill_h_gaps(grid, fill=2):
    """In each row, recolor to fill every cell lying strictly between two cells of the same non-background color (background = most common color)."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for row in out:
        cols = [j for j, v in enumerate(row) if v != bg]
        for a, b in zip(cols, cols[1:]):
            if all(row[j] == bg for j in range(a + 1, b)):
                for j in range(a + 1, b):
                    row[j] = fill
    return out
